Given an array arr[] and an integer target, determine if there exists a triplet in the array whose sum equals the given target.Return true if such a triplet exists, otherwise, return false.Examples: Input: arr[] = [1, 4, 45, 6, 10, 8], target = 13Output: trueExplanation: The triplet [1, 4, 8] sums up to 13Input: arr[] = [1, 2, 4, 3, 6, 7], target = 10 Output: trueExplanation: The triplets [1, 3, 6] and [1, 2, 7] both sum to 10. Input: arr[] = [40, 20, 10, 3, 6, 7], sum = 24 Output: falseExplanation:  No triplet in the array sums to 24.Try It YourselfTable of Content[Naive Approach] Generating All Triplets - O(n^3) Time and O(1) Space[Better Approach] Hash Set - O(n^2) Time and O(n) Space[Expected Approach] Sorting and Two Pointer - O(n^2) Time and O(1) Space[Naive Approach] Generating All Triplets - O(n^3) Time and O(1) SpaceA simple method is to generate all possible triplets and compare the sum of every triplet with the given target. If the sum is equal to target, return true. Otherwise, return false.
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool hasTripletSum(vector<int>& arr, int target) {
    int n = arr.size();

    // Fix the first element as arr[i] 
    for (int i = 0; i < n - 2; i++) {

        // Fix the second element as arr[j] 
        for (int j = i + 1; j < n - 1; j++) {

            // Now look for the third number 
            for (int k = j + 1; k < n; k++) { 
                if (arr[i] + arr[j] + arr[k] == target)
                    return true; 
            } 
        } 
    } 

    return false; 
} 

int main() { 
    vector<int> arr = { 1, 4, 45, 6, 10, 8 }; 
    int target = 13; 
    if(hasTripletSum(arr, target))
        cout << "true";
    else
        cout << "false";
    return 0; 
}


